    {"t": "图灵测试", "a": ["Turing Test"], "c": "科技",      "b": "图灵测试由图灵一九五零年提出。若人无法分辨对话另一端是人还是机器。则可认为机器具有智能。是 AI 经典判据。",      "r": ["人工智能", "图灵"]},     {"t": "图灵完备", "a": ["Turing complete", "图灵完全", "图灵完备性"], "c": "计算机科学",      "b": "图灵完备指一个系统能模拟通用图灵机进行计算。判断标准是看它是否具备三个基本能力：条件分支（if/else、选择跳转）、循环与递归（while/for、反复执行、可无限运行）、以及无限或可增长的存储。满足这些即可计算任何可计算问题，例如编程语言 Python、C、Java 都是图灵完备的；而 HTML 或正则表达式（无递归）则不是。",      "r": ["图灵机", "可计算性", "编程语言", "图灵"]},
