# v1.8 Alpha · 文字画面模板 (SCENE_TPL)
#   主程序 _scene_storyboard()/_scene_written() 用它拼"4 格分镜"与兜底文字描写。
#   键: 远 / 中 / 近 / 落 (四个镜头) 与 写 (整段文字画面); 句内 {t} 会被换成主题。
#   挑选方式是确定性的(按主题字数取模), 同一主题永远得到同一套分镜, 不随机。
# ══════════════════════════════════════════════════════════════════════════
SCENE_TPL = {
    "远": [
        "远景先铺开：{t}待在画面正中偏后，天色压得很低，四周留白很多。",
        "镜头拉到最远——{t}变成地平线上的一个点，风把远处的东西吹得有点晃。",
        "先给一个大全景：{t}和小得多的环境一起入画，让人先觉得天地很宽。",
    ],
    "中": [
        "中景推近：{t}的轮廓清楚了，能看见它此刻的姿态。",
        "镜头收半格——{t}占了画面一半，旁边留出一点呼吸的余地。",
        "中景交代动作：{t}正在做它的那件事，光落在它身上，不刺眼。",
    ],
    "近": [
        "近景切上去：{t}的细节被放大，边缘的光毛茸茸的。",
        "贴脸一拍——{t}的纹理、温度和那点小情绪，全都藏不住了。",
        "近景定格：{t}的某个局部被单独拎出来，别的都虚成背景。",
    ],
    "落": [
        "落幅收在一个静止的小动作上，画面定住，让人多看那一眼。",
        "最后停在{t}身上，不动了——剩下的交给看的人自己补。",
        "落幅留一帧安静：{t}在那儿，风还在吹，但什么都不急着发生。",
    ],
    "写": [
        "画面里是「{t}」：光从侧面斜进来，边缘有一点毛，动作停在半空——不看解释，也看得懂。",
        "把这一刻摊开写：「{t}」占住画面中心，其余的都被虚成一片安静的颜色，很轻，但很有存在感。",
        "「{t}」——不吵不闹地待在那儿，光线绕着它走了一圈，像谁悄悄给它描了道边。",
    ],
}


