# ============================================================
# v1.8 Alpha: 网络梗库 (MEME_KB) —— 让小方听得懂人话外的"人话"
#   kws=触发词(取最长匹配, 避免误伤正常句子) / name=梗名 / mean=这梗什么意思
#   pol=情绪极性(正/负/中性, 用于情感判读) / say=接梗时小方的回应(可留空)
#   只收中性日常梗: 不涉政治/不涉具体真人/不含低俗指向。
# ============================================================
