#   用户投诉的核心病灶: "明明正确识别了用户需要什么, 答出来却牛头不对马嘴"。
#   根因: 旧路由只按「话题词」分流, 从不判「用户问的是这个东西的哪一面」——
#     于是"有什么好玩的游戏"被当成"游戏是什么"去翻库, "讲讲你自己的架构"
#     被当成"小方工作室是谁"去答工作室。修法: 拆成两层再组合路由。
#     ① 主体 subject = 在说谁 / 什么东西;  ② 焦点 focus = 想问它的哪一面。
