             # V1.8 Alpha: 补"求方案/求建议/求注意事项"整族 —— 旧表只认"怎么做/怎样/如何",
             #   于是 "给我一份学英语的方案 / 买笔记本要注意什么 / 我想系统学一下数据结构"
             #   这类同样是"要方法"的问句, 十二个诉求一个线索都命中不了, 只能靠先验瞎猜后反问。
             #   这几族的共同点是"要一份可照着做的路径", 与 plan 产物同源, 故并入 how。
             "方案", "规划", "规划一下", "路线", "路线图", "学习路径", "学习路线",
             "注意事项", "要注意", "该注意", "注意什么", "注意哪些", "需要注意",
             "系统学", "系统学习", "系统地学", "系统练", "系统了解",
