    # ⑫ 第 12 个诉求维度: 跟进进度 —— "长线任务"的当下快照。
    #   与 HOR(第 5 维)配合: HOR 判出"这是件长期的活", 本维度判"用户此刻要看的是
    #   走到哪了", 于是产物形态是"进度盘点"(完成度 + 已完成 + 待办 + 下一步),
    #   而不是又生成一版方案。旧表没有这一维, "看进度"只能退化成瞎猜。
    {"key": "track", "label": "跟进进度", "w": 1.01, "arts": ["progress"],
     "kws": ["进度", "进展", "到哪了", "到哪一步", "走到哪", "进行到哪", "做到哪",
             "完成多少", "完成得怎么样", "完成了没", "完成了吗", "搞定没", "搞定没有",
             "做完没", "做完没有", "打卡了吗", "坚持几天", "连续几天", "坚持了多久",
             "跟进", "追踪", "看进度", "查进度", "任务状态", "计划执行", "执行情况"],
     "pats": [r"(进度|进展)(如何|怎么样|呢|啦|了)?",
              r"(到|走|进行)到(哪|第几步|哪一步)",
              r"(完成|搞定|做完|打卡|坚持)(了)?(没|没有|吗|多久|几天)",
              r"(看|查|盯)(一下)?(进度|进展)"]},

