# ③ ART 产物形态 —— 由 (ACT × DOM × MOD) 推导交付物长什么样。
#   这是"精准打击"的最后一公里: 同样问游戏, "推荐"要 namelist, "什么是"要 definition,
#   两句的 ACT 不同 → ART 不同 → 应答形态不同。旧引擎缺的就是这一层。
TIR_ART_KB = {
    "runnable_code": {"label": "可直接运行的代码", "hint": "给完整可跑代码 + 关键注释, 附运行方式"},
    "prose":         {"label": "成篇文章", "hint": "按文体成篇, 有开头/主体/收束, 不交提纲"},
    "plan":          {"label": "步骤方案", "hint": "给有序步骤 + 每步要点, 可照着做"},
    "progress":      {"label": "进度盘点", "hint": "先报当前完成度, 再列已完成/待办/下一步, 别只丢一个数字"},
    "namelist":      {"label": "具体名单", "hint": "给具体名称 + 一句话理由, 不给类型分类"},
    "definition":    {"label": "定义解释", "hint": "先用一句话定义, 再补关键点, 不夹带无关信息"},
    "table":         {"label": "对比表", "hint": "按同一组维度逐项对照, 最后给一句取舍结论"},
    "scene":         {"label": "文字画面", "hint": "把画面写出来, 不给算法描述"},
    "live_data":     {"label": "实时数据", "hint": "取真实数据源, 不编造数值"},
    "number":        {"label": "数值结果", "hint": "给算式 + 结果 + 必要步骤"},
    "talk":          {"label": "对话回应", "hint": "自然接话, 简洁有温度"},
    "answer":        {"label": "通用作答", "hint": "直接回答被问到的那一点"},
}

