# ⑦ 置信闸门 —— "真没听懂"就反问, 绝不硬猜。这是治"牛头不对马嘴"的最后一道闸:
#   猜错的代价远大于多问一句。gap = top1 - top2 (归一化后)。
TIR_GATE = {
    "ok": 0.16,        # ≥ 这个差距: 听懂了, 直接照 ACT×DOM×ART 办
    "ask": 0.055,      # < 这个差距: 完全没方向, 必须反问
    # 介于两者之间: 有倾向但不稳 → 若是"要我动手做东西"的复杂任务, 也反问;
    #   若只是随口一问, 仍按 top1 作答(避免把简单闲聊变成审讯)。
}

# ⑧ 反问模板 —— 按 ACT 给出**具体可选**的候选, 让用户一点就选(不是空泛的"请再说清楚")。
