# ══════════════════════════════════════════════════════════════════════
# v1.8 Alpha · 代码素养库 —— "什么才是最好的代码"
#   用户要: "也要让小方的代码有规范, 自己可以自己搞变量, 写游戏,
#   学会代码优化, 当然你也要给小方代码优化啊, 小方要学会什么才是最好的代码?"
#   覆盖: 好代码标准 / 命名规范 / 优化手法 / 坏味道 / 分语言风格 / 上手路径。
# ══════════════════════════════════════════════════════════════════════
CODE_QUALITY_KB = [
    (["什么是最好的代码", "什么是好代码", "好代码", "优秀代码", "高质量代码",
      "代码质量", "怎么写出好代码", "好代码的标准"], """**最好的代码不是写得最巧的，是最容易被下一个人看懂的。** 我按重要性排一下：

**① 可读性 > 聪明**
代码被读的次数远多于被写的次数。`i` 换成 `item_index`、嵌套三层拆成小函数、魔法数字命名成常量——这些都是"给别人省事，也给自己省事"。

**② 命名即注释**
`elapsed_seconds` 比 `es` 好；`is_valid` 比 `flag` 好。**名字取对了，一半注释就省了**；名字取错了，十行注释也救不回来。

**③ 单一职责**
一个函数只做一件事。"读配置 + 校验 + 连数据库 + 写日志"塞在一个函数里，出问题根本没法定位。判断标准很简单：**描述它的时候，你会不会用到"并且"**。

**④ 边界和异常先想清楚**
空输入、超长输入、除零、文件不存在、网络超时——**好代码是先想坏情况，再写好情况**。

**⑤ 复杂度可控**
能 O(n) 就别 O(n²)；能用字典查就别用列表遍历。过早优化是坑，但**明显的坏复杂度不能留**。

**⑥ 可测试**
函数越"纯"（输入定则输出定，不依赖全局状态）越好测。写不出测试的代码，通常耦合太紧。

**一句话总结：好代码 = 正确 + 清晰 + 好改。** 三者冲突时，优先顺序是**正确 → 清晰 → 好改**。"""),
    (["命名规范", "怎么起变量名", "变量命名", "命名", "起名", "怎么命名",
      "函数命名", "类命名"], """命名是代码里最高频的"小事"，我把各语言通用的规则列清楚：

**通用规则**

| 对象 | 规矩 | 好例子 | 坏例子 |
| --- | --- | --- | --- |
| 变量 | 名词，小写下划线 | `user_count` | `uc`, `data1`, `tmp` |
| 函数 | 动词开头 | `fetch_user`, `is_valid` | `user`, `handle` |
| 布尔值 | `is_` / `has_` / `can_` 开头 | `is_ready`, `has_perm` | `flag`, `ok2` |
| 常量 | 全大写下划线 | `MAX_RETRY` | `maxretry`, `m` |
| 类 | 大驼峰名词 | `OrderService` | `order_service` |
| 私有 | 前缀下划线 | `_cache` | `cache2` |
| 循环下标 | 语义化，不用 i/j/k 混 | `row_index` | `i`, `j`, `k`, `ii` |

**四条硬底线**
1. **不用拼音 + 英文混拼**（`getYonghuList` ❌）
2. **不用无意义单字母**，只有循环计数、坐标 x/y、数学变量可以例外
3. **同义词要统一**：项目里 all 用 `fetch` 就别另一处写 `get`、`query`、`load` 混着来
4. **缩写只留公认的**：`id`、`url`、`http` 可以；`usr`、`msg_num`、`cfg2` 不行

**分语言风格**

| 语言 | 变量 / 函数 | 类 / 常量 |
| --- | --- | --- |
| Python | `snake_case` | `PascalCase` / `UPPER_CASE` |
| JavaScript / TS | `camelCase` | `PascalCase` / `UPPER_CASE` |
| Java | `camelCase` | `PascalCase` / `UPPER_CASE` |
| C / C++ | `snake_case` | `PascalCase` / `UPPER_CASE` |
| Go | `camelCase`（导出用 `PascalCase`） | 同左 |
| Rust | `snake_case` | `PascalCase` / `UPPER_CASE` |"""),
    (["代码优化", "怎么优化代码", "优化代码", "性能优化", "代码太慢", "提速",
      "怎么让代码更快", "优化建议"], """代码优化我按"性价比"排序，**别一上来就抠细节**：

**第 0 步 · 先测量，别猜**
用 `time.perf_counter()` / `cProfile` 找出真正的热点。凭直觉优化，90% 的时间会花在无关紧要的 3% 上。

**第 1 步 · 换算法（收益最大）**
- 列表里查存在 → 换 `set` / `dict`，O(n) → O(1)
- 双层循环找配对 → 用哈希表一次遍历
- 重复排序 → 排序一次，后续复用
- 字符串反复拼接 → 用 `"".join(list)`

**第 2 步 · 减少重复计算**
循环里不变的表达式提到循环外；重复调用的函数结果用缓存（`functools.lru_cache`）；递归加记忆化。

**第 3 步 · 用对数据结构**
需要两端增删用 `deque`；需要有序去重用 `dict`；需要定长环形缓冲区用数组下标取模；计数用 `collections.Counter`。

**第 4 步 · 借力现成库**
数值计算交给 NumPy 向量化（**不要手写 Python 循环**）；批量请求用连接池 + 并发（`concurrent.futures`）；正则提前 `re.compile`。

**第 5 步 · 微观优化（最后做）**
局部变量绑定、避免属性链式访问、减少对象创建。这些收益小，代码还会变丑，**除非热点明确否则别做**。

**一句话：先让它对，再让它清晰，最后才让它快。**"""),
    (["坏味道", "代码坏味道", "代码很乱", "重构", "怎么重构", "代码 smells",
      "代码臭", "烂代码"], """我列一份"代码坏味道"清单，逐条给解法：

| 坏味道 | 症状 | 解法 |
| --- | --- | --- |
| 超长函数 | 一个函数超过 50 行、缩进四层 | 按职责拆小函数，用"提取方法" |
| 重复代码 | 同样的逻辑复制三处 | 抽公共函数 / 参数化 |
| 魔法数字 | 代码里冒出 `86400`、`0.85` | 提成命名常量 |
| 全局变量满天飞 | 到处 `global`、模块级可变状态 | 收进类 / 用参数传递 |
| 参数过多 | 函数 6 个以上参数 | 打包成配置对象 / dataclass |
| 注释过时 | 代码改了注释没改 | 注释讲"为什么"，不讲"是什么" |
| 深层嵌套 | `if` 里套 `for` 里套 `if` | 早返回（guard clause）拍平 |
| 硬编码路径 | `"C:/Users/xxx/a.txt"` | 配置化 / `pathlib` |
| 裸 `except` | `except:` 吞掉一切 | 捕获具体异常并记录 |
| 表里不一 | 函数叫 `get_x` 却改了数据 | 改名，或拆掉副作用 |

**重构的安全做法**：先有一组测试 → 小步改 → 每步都跑测试 → 行为不变只改结构。**没有测试的重构 = 拆炸弹。**"""),
    (["写代码的步骤", "怎么开始写代码", "写代码流程", "编程入门", "怎么学编程",
      "从零开始写", "怎么练编程"], """我给你一条能落地的路径，**从"能跑"到"能维护"**：

**① 先写清需求，再动键盘**
一句话说清"输入什么 → 做什么 → 输出什么"。说不清就说明还没想明白，这时写代码必翻车。

**② 定数据结构**
数据结构定了，算法往往就出来了。先想"要用什么存这些数据"，再想"怎么处理它"。

**③ 写最小可跑版本**
哪怕函数体先 `pass`，先把骨架和调用链跑通，再往里填。

**④ 补边界**
空、单个、超长、重复、异常输入各跑一遍。

**⑤ 重构 + 加测试**
把能抽的抽出来，给关键函数写断言，让改动有安全网。

**⑥ 加注释讲"为什么"**
记录"为什么这么选"，而不是"这行在做什么"。

**练法建议**：每天一个小题目（排序、字符串处理、模拟类），写完**让别人读一遍**——读不懂的地方就是该改的地方。"""),
]


